const $=id=>document.getElementById(id);
const canvas=$('board-canvas'), workspace=$('workspace'), ctx=canvas.getContext('2d');
const palette=['#243b43','#167d8d','#7265b2','#e47550','#d9a52b','#ffffff'];
const kinds=new Set(['pen','marker','line','arrow','rectangle','ellipse','triangle','text','image','cube','pyramid','cylinder','cone','axes','numberline','graph','formula']);
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const clone=x=>JSON.parse(JSON.stringify(x));
const state={tool:'select',color:palette[0],width:3,fill:false,dashed:false,snap:false,fontSize:26,selected:new Set(),view:{x:100,y:80,scale:1},objects:[],grid:'dots',title:'Первый урок',id:uid()};
let width=0,height=0,dpr=1,drag=null,space=false,dirty=false,renderPending=false,history=[],historyIndex=-1,saveTimer,db=null,boards=new Map(),saveSerial=0,mutationRevision=0,lastPen=0,loadingBoard=false,lastHistoryGroup=null,lastHistoryTime=0;
const images=new Map();
const pendingRestores=new Set();
let ai=null,input=null,inputCheckpoint=null;
if(window.matchMedia('(max-width:900px)').matches)workspace.classList.add('panel-collapsed');
const tips={select:'ПКМ — двигать холст · колесо — масштаб · рамка — размер объекта',hand:'ПКМ или пробел + перетаскивание — холст · колесо — масштаб',pen:'Рисуйте мышью или пером · ПКМ — перемещение · колесо — масштаб',marker:'Полупрозрачный маркер · цвет и толщину можно менять справа',eraser:'Нажмите или проведите по объектам, чтобы удалить их',line:'Потяните для линии · Shift — шаг угла 45°',arrow:'Потяните для стрелки · Shift — шаг угла 45°',rectangle:'Потяните для прямоугольника · Shift — квадрат',ellipse:'Потяните для эллипса · Shift — окружность',triangle:'Потяните для треугольника',text:'Нажмите на доску, чтобы добавить текст или формулу'};
function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),4200)}
function screenPoint(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function worldPoint(p){return{x:(p.x-state.view.x)/state.view.scale,y:(p.y-state.view.y)/state.view.scale}}
function snap(p){return state.snap?{x:Math.round(p.x/20)*20,y:Math.round(p.y/20)*20}:p}
function objBounds(o){return {x:Math.min(o.x,o.x+o.w),y:Math.min(o.y,o.y+o.h),w:Math.abs(o.w),h:Math.abs(o.h)}}
function union(objs){if(!objs.length)return null;let x=Infinity,y=Infinity,r=-Infinity,b=-Infinity;for(const o of objs){const a=objBounds(o);x=Math.min(x,a.x);y=Math.min(y,a.y);r=Math.max(r,a.x+a.w);b=Math.max(b,a.y+a.h)}return{x,y,w:Math.max(r-x,1),h:Math.max(b-y,1)}}
function chosen(){return state.objects.filter(o=>state.selected.has(o.id))}
function distanceSeg(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,d=dx*dx+dy*dy;const t=d?Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/d)):0;return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy)}
function hit(o,p){const b=objBounds(o),pad=Math.max(6/state.view.scale,o.width||1);if(p.x<b.x-pad||p.x>b.x+b.w+pad||p.y<b.y-pad||p.y>b.y+b.h+pad)return false;if(o.type==='pen'||o.type==='marker'){for(let i=1;i<o.points.length;i++)if(distanceSeg(p,{x:o.x+o.points[i-1].x,y:o.y+o.points[i-1].y},{x:o.x+o.points[i].x,y:o.y+o.points[i].y})<pad+(o.type==='marker'?o.width*2:o.width))return true;return o.points.length===1&&Math.hypot(p.x-o.x-o.points[0].x,p.y-o.y-o.points[0].y)<pad}if(o.type==='line'||o.type==='arrow')return distanceSeg(p,{x:o.x,y:o.y},{x:o.x+o.w,y:o.y+o.h})<pad;return true}
function hitTop(p){for(let i=state.objects.length-1;i>=0;i--)if(hit(state.objects[i],p))return state.objects[i];return null}
function scheduleRender(){if(renderPending)return;renderPending=true;requestAnimationFrame(()=>{renderPending=false;render()})}
function grid(c,w,h,v,mode){if(mode==='blank')return;const base=20;let step=base*v.scale;while(step<12)step*=2;while(step>65)step/=2;const ox=((v.x%step)+step)%step,oy=((v.y%step)+step)%step;c.save();c.strokeStyle='#e3e9e7';c.fillStyle='#d6dfdc';c.lineWidth=1;if(mode==='dots'){for(let x=ox;x<w;x+=step)for(let y=oy;y<h;y+=step){c.beginPath();c.arc(x,y,.8,0,Math.PI*2);c.fill()}}else{c.beginPath();for(let x=ox;x<w;x+=step){c.moveTo(Math.round(x)+.5,0);c.lineTo(Math.round(x)+.5,h)}for(let y=oy;y<h;y+=step){c.moveTo(0,Math.round(y)+.5);c.lineTo(w,Math.round(y)+.5)}c.stroke();if(mode==='axes'){c.strokeStyle='#8fa6a0';c.lineWidth=1.5;c.beginPath();c.moveTo(v.x,0);c.lineTo(v.x,h);c.moveTo(0,v.y);c.lineTo(w,v.y);c.stroke();c.font='12px system-ui';c.fillStyle='#6a817a';c.fillText('x',w-18,v.y-8);c.fillText('y',v.x+8,18)}}c.restore()}
function drawObject(c,o){c.save();c.strokeStyle=o.color;c.fillStyle=o.color;c.lineWidth=o.width||2;c.lineJoin='round';c.lineCap='round';c.setLineDash(o.dashed?[8,6]:[]);if(o.type==='formula'){drawFormula(c,o,scheduleRender);c.restore();return}if(drawMathObject(c,o)){c.restore();return}const x=o.x,y=o.y,w=o.w,h=o.h;const fill=()=>{if(o.fill){c.save();c.globalAlpha=.12;c.fill();c.restore()}c.stroke()};if(o.type==='pen'||o.type==='marker'){c.globalAlpha=o.type==='marker'?.3:1;c.lineWidth=(o.width||3)*(o.type==='marker'?4:1);const p=o.points;if(p.length===1){c.beginPath();c.arc(x+p[0].x,y+p[0].y,c.lineWidth/2,0,Math.PI*2);c.fill()}else if(p.length){c.beginPath();c.moveTo(x+p[0].x,y+p[0].y);for(let i=1;i<p.length-1;i++)c.quadraticCurveTo(x+p[i].x,y+p[i].y,x+(p[i].x+p[i+1].x)/2,y+(p[i].y+p[i+1].y)/2);c.lineTo(x+p.at(-1).x,y+p.at(-1).y);c.stroke()}}else if(o.type==='line'||o.type==='arrow'){c.beginPath();c.moveTo(x,y);c.lineTo(x+w,y+h);c.stroke();if(o.type==='arrow'){const a=Math.atan2(h,w),l=Math.max(12,(o.width||2)*4);c.setLineDash([]);c.beginPath();c.moveTo(x+w-l*Math.cos(a-.45),y+h-l*Math.sin(a-.45));c.lineTo(x+w,y+h);c.lineTo(x+w-l*Math.cos(a+.45),y+h-l*Math.sin(a+.45));c.stroke()}}else if(o.type==='rectangle'){c.beginPath();c.rect(x,y,w,h);fill()}else if(o.type==='ellipse'){c.beginPath();c.ellipse(x+w/2,y+h/2,Math.max(.1,w/2),Math.max(.1,h/2),0,0,Math.PI*2);fill()}else if(o.type==='triangle'){c.beginPath();c.moveTo(x,y+h);c.lineTo(o.right?x:x+w/2,y);c.lineTo(x+w,y+h);c.closePath();fill();if(o.right){c.beginPath();c.moveTo(x,y+h-17);c.lineTo(x+17,y+h-17);c.lineTo(x+17,y+h);c.stroke()}}else if(o.type==='text'){c.font=`${o.bold?'600':'400'} ${o.fontSize||26}px ${o.serif?'Georgia, serif':'Inter, system-ui, sans-serif'}`;c.textBaseline='top';for(const [i,line] of (o.text||'').split('\n').entries())c.fillText(line,x,y+i*(o.fontSize||26)*1.35)}else if(o.type==='image'){let im=images.get(o.src);if(!im){im=new Image();images.set(o.src,im);im.onload=scheduleRender;im.onerror=()=>toast('Не удалось прочитать изображение');im.src=o.src}if(im.complete&&im.naturalWidth)c.drawImage(im,x,y,w,h);else{c.fillStyle='#edf2f0';c.fillRect(x,y,w,h)}}c.restore()}
function render(){if(!width)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);ctx.fillStyle='#fbfcfa';ctx.fillRect(0,0,width,height);grid(ctx,width,height,state.view,state.grid);ctx.save();ctx.translate(state.view.x,state.view.y);ctx.scale(state.view.scale,state.view.scale);for(const o of state.objects)drawObject(ctx,o);const selected=chosen(),b=union(selected);if(b){const s=state.view.scale;ctx.save();ctx.strokeStyle='#167d8d';ctx.lineWidth=1.2/s;ctx.setLineDash([5/s,4/s]);ctx.strokeRect(b.x-5/s,b.y-5/s,b.w+10/s,b.h+10/s);ctx.setLineDash([]);if(!selected.some(o=>o.locked))for(const p of resizeHandles(b)){ctx.fillStyle='white';ctx.fillRect(p.x-4/s,p.y-4/s,8/s,8/s);ctx.strokeRect(p.x-4/s,p.y-4/s,8/s,8/s)}if(selected.some(o=>o.locked)){ctx.fillStyle='#167d8d';ctx.font=`${12/s}px system-ui`;ctx.fillText('Закреплено',b.x,b.y-12/s)}ctx.restore()}if(drag?.mode==='marquee'){ctx.fillStyle='rgba(22,125,141,.07)';ctx.strokeStyle='#167d8d';ctx.lineWidth=1/state.view.scale;ctx.fillRect(drag.start.x,drag.start.y,drag.end.x-drag.start.x,drag.end.y-drag.start.y);ctx.strokeRect(drag.start.x,drag.start.y,drag.end.x-drag.start.x,drag.end.y-drag.start.y)}ctx.restore();$('zoom-value').textContent=Math.round(state.view.scale*100)+'%';$('zoom-slider').value=Math.round(100*Math.log(state.view.scale/.08)/Math.log(75));$('zoom-slider').setAttribute('aria-valuetext',Math.round(state.view.scale*100)+'%');document.querySelector('[data-action="undo"]').disabled=historyIndex<=0;document.querySelector('[data-action="redo"]').disabled=historyIndex>=history.length-1;ai?.updateSelection(b,state.view,{width,height},!!drag||input?.isNavigating())}
function corners(b){return[{x:b.x,y:b.y},{x:b.x+b.w,y:b.y},{x:b.x+b.w,y:b.y+b.h},{x:b.x,y:b.y+b.h}]}
function resizeHandles(b){return [[0,0,'nwse-resize'],[.5,0,'ns-resize'],[1,0,'nesw-resize'],[1,.5,'ew-resize'],[1,1,'nwse-resize'],[.5,1,'ns-resize'],[0,1,'nesw-resize'],[0,.5,'ew-resize']].map(([ux,uy,cursor])=>({x:b.x+b.w*ux,y:b.y+b.h*uy,ux,uy,cursor}))}
function snapshot(){return JSON.stringify({objects:state.objects,grid:state.grid,title:state.title})}
function commit(group=null){const s=snapshot(),now=Date.now();if(history[historyIndex]!==s){if(group&&group===lastHistoryGroup&&now-lastHistoryTime<350&&historyIndex===history.length-1&&historyIndex>0)history[historyIndex]=s;else{history=history.slice(0,historyIndex+1);history.push(s);if(history.length>65)history.shift();historyIndex=history.length-1}}lastHistoryGroup=group;lastHistoryTime=now;scheduleSave();scheduleRender();syncSelection()}
function undo(delta){input?.cancel();lastHistoryGroup=null;const i=historyIndex+delta;if(i<0||i>=history.length)return;historyIndex=i;Object.assign(state,JSON.parse(history[i]));state.selected.clear();$('board-title').value=state.title;$('grid-mode').value=state.grid;scheduleSave();scheduleRender();syncSelection()}
function setTool(t){input?.cancel();state.tool=t;state.selected.clear();document.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===t);b.setAttribute('aria-pressed',String(b.dataset.tool===t))});canvas.style.cursor=t==='hand'?'grab':t==='select'?'default':t==='text'?'text':'crosshair';$('tool-hint').textContent=tips[t]||'';scheduleRender();syncSelection()}
function syncSelection(){const n=chosen().length;for(const a of ['delete','duplicate','lock','front','back']){const el=document.querySelector(`[data-action="${a}"]`);if(el)el.disabled=!n}const one=n===1?chosen()[0]:null;const resetGraph=document.querySelector('[data-action="reset-graph-view"]');if(resetGraph)resetGraph.disabled=!one||one.type!=='graph'||one.locked;if(one){state.color=one.color;state.width=one.width||3;state.fill=!!one.fill;state.dashed=!!one.dashed;$('custom-color').value=state.color;$('stroke-width').value=state.width;$('width-value').textContent=state.width;$('fill-toggle').checked=state.fill;$('dashed-toggle').checked=state.dashed;document.querySelectorAll('[data-color]').forEach(b=>{b.classList.toggle('active',b.dataset.color===state.color);b.setAttribute('aria-pressed',String(b.dataset.color===state.color))});if(one.type==='text'||one.type==='formula'){$('font-size').value=one.fontSize;state.fontSize=one.fontSize}}const el=document.querySelector('[data-action="lock"]');if(el){el.classList.toggle('active',n>0&&chosen().every(o=>o.locked));el.title=n>0&&chosen().every(o=>o.locked)?'Открепить':'Закрепить'}const title=$('selection-label');if(title)title.textContent=n?`Выделено: ${n}`:'Стиль объектов'}
function fresh(type,p){return{id:uid(),type,x:p.x,y:p.y,w:0,h:0,color:state.color,width:state.width,fill:state.fill,dashed:state.dashed}}
function gestureEnd(){if(!drag)return;const d=drag;drag=null;if(d.mode==='text-tap'){if(!d.moved)textDialog(d.start)}else if(d.mode==='draw'){const o=d.object;if(o.type==='pen'||o.type==='marker'){const xs=o.points.map(p=>p.x),ys=o.points.map(p=>p.y);const minX=Math.min(...xs),minY=Math.min(...ys);o.x+=minX;o.y+=minY;o.points.forEach(p=>{p.x-=minX;p.y-=minY});o.w=Math.max(...xs)-minX||1;o.h=Math.max(...ys)-minY||1}else if(Math.abs(o.w)<3&&Math.abs(o.h)<3)state.objects=state.objects.filter(a=>a.id!==o.id);commit()}else if(['move','resize','erase'].includes(d.mode)){commit()}else if(d.mode==='marquee'){const b={x:Math.min(d.start.x,d.end.x),y:Math.min(d.start.y,d.end.y),w:Math.abs(d.end.x-d.start.x),h:Math.abs(d.end.y-d.start.y)};for(const o of state.objects){const a=objBounds(o);if(a.x>=b.x&&a.y>=b.y&&a.x+a.w<=b.x+b.w&&a.y+a.h<=b.y+b.h)state.selected.add(o.id)}syncSelection()}else if(d.mode==='pan')scheduleSave();canvas.style.cursor=state.tool==='hand'?'grab':state.tool==='select'?'default':state.tool==='text'?'text':'crosshair';scheduleRender()}
function beginPointer(e){if(![0,1,2].includes(e.button))return;if(drag)return;e.preventDefault();const sp=screenPoint(e),p=snap(worldPoint(sp));canvas.setPointerCapture(e.pointerId);if(state.tool==='hand'||space||e.button===1||e.button===2){drag={mode:'pan',screen:sp,view:{...state.view},pointer:e.pointerId};canvas.style.cursor='grabbing';return}if(state.tool==='text'){if(e.pointerType==='touch')drag={mode:'text-tap',start:p,screen:sp,pointer:e.pointerId};else textDialog(p);return}if(state.tool==='select'){const bs=union(chosen());if(bs&&!chosen().some(o=>o.locked)){const handle=resizeHandles(bs).find(a=>Math.hypot(a.x-p.x,a.y-p.y)<9/state.view.scale);if(handle){canvas.style.cursor=handle.cursor;drag={mode:'resize',start:p,box:bs,handle,original:clone(chosen()),pointer:e.pointerId};return}}const o=hitTop(p);if(o){if(e.shiftKey){state.selected.has(o.id)?state.selected.delete(o.id):state.selected.add(o.id)}else if(!state.selected.has(o.id)){state.selected.clear();state.selected.add(o.id)}const movable=chosen().filter(a=>!a.locked);if(movable.length)drag={mode:'move',start:p,original:clone(movable),pointer:e.pointerId};else if(o.locked)toast('Объект закреплён. Нажмите на замок, чтобы открепить.')}else{if(!e.shiftKey)state.selected.clear();drag={mode:'marquee',start:p,end:p,pointer:e.pointerId}}syncSelection();scheduleRender();return}if(state.tool==='eraser'){drag={mode:'erase',pointer:e.pointerId};eraseAt(p);return}const o=fresh(state.tool,p);if(o.type==='pen'||o.type==='marker')o.points=[{x:0,y:0}];state.objects.push(o);drag={mode:'draw',start:p,object:o,pointer:e.pointerId};scheduleRender()}
function eraseAt(p){const o=hitTop(p);if(o&&!o.locked){state.objects=state.objects.filter(x=>x.id!==o.id);scheduleRender()}}
function movePointer(e){if(!drag){const p=worldPoint(screenPoint(e)),o=hitTop(p),b=union(chosen());const handle=state.tool==='select'&&b&&!chosen().some(a=>a.locked)?resizeHandles(b).find(a=>Math.hypot(a.x-p.x,a.y-p.y)<9/state.view.scale):null;canvas.style.cursor=space||state.tool==='hand'?'grab':handle?handle.cursor:state.tool==='select'?'default':state.tool==='text'?'text':'crosshair';$('tool-hint').textContent=o?.type==='graph'&&!o.locked?'Колесо — масштаб графика · Ctrl + колесо — масштаб доски · рамка — размер':tips[state.tool]||'';return}if(drag.pointer!==e.pointerId)return;const sp=screenPoint(e),p=snap(worldPoint(sp));if(drag.mode==='text-tap'){if(Math.hypot(sp.x-drag.screen.x,sp.y-drag.screen.y)>12)drag.moved=true}else if(drag.mode==='pan'){state.view.x=drag.view.x+sp.x-drag.screen.x;state.view.y=drag.view.y+sp.y-drag.screen.y}else if(drag.mode==='erase'){eraseAt(p)}else if(drag.mode==='draw'){const o=drag.object;if(o.points){const evs=e.getCoalescedEvents?.()||[e];for(const ev of evs.length?evs:[e]){const q=worldPoint(screenPoint(ev)),last=o.points.at(-1);if(Math.hypot(q.x-o.x-last.x,q.y-o.y-last.y)>.6/state.view.scale&&o.points.length<20000)o.points.push({x:q.x-o.x,y:q.y-o.y})}}else{let dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(e.shiftKey){if(o.type==='line'||o.type==='arrow'){const a=Math.round(Math.atan2(dy,dx)/(Math.PI/4))*Math.PI/4,l=Math.hypot(dx,dy);dx=l*Math.cos(a);dy=l*Math.sin(a)}else{const side=Math.max(Math.abs(dx),Math.abs(dy));dx=Math.sign(dx||1)*side;dy=Math.sign(dy||1)*side}}if(o.type==='line'||o.type==='arrow'){o.w=dx;o.h=dy}else{o.x=drag.start.x+Math.min(0,dx);o.y=drag.start.y+Math.min(0,dy);o.w=Math.abs(dx);o.h=Math.abs(dy)}}}else if(drag.mode==='move'){const dx=p.x-drag.start.x,dy=p.y-drag.start.y;for(const orig of drag.original){const o=state.objects.find(a=>a.id===orig.id);o.x=orig.x+dx;o.y=orig.y+dy}}else if(drag.mode==='resize'){const b=drag.box,{ux,uy}=drag.handle;let nx=ux===0?Math.min(p.x,b.x+b.w-10):b.x,ny=uy===0?Math.min(p.y,b.y+b.h-10):b.y;let nw=ux===1?Math.max(10,p.x-b.x):b.x+b.w-nx,nh=uy===1?Math.max(10,p.y-b.y):b.y+b.h-ny;if(e.shiftKey&&ux!==.5&&uy!==.5){const k=Math.max(nw/b.w,nh/b.h);nw=b.w*k;nh=b.h*k;if(ux===0)nx=b.x+b.w-nw;if(uy===0)ny=b.y+b.h-nh}const sx=nw/b.w,sy=nh/b.h;for(const orig of drag.original){const o=state.objects.find(a=>a.id===orig.id);o.x=nx+(orig.x-b.x)*sx;o.y=ny+(orig.y-b.y)*sy;o.w=orig.w*sx;o.h=orig.h*sy;if(orig.points)o.points=orig.points.map(q=>({x:q.x*sx,y:q.y*sy}));if(orig.type==='formula'){const k=Math.min(sx,sy);o.w=orig.w*k;o.h=orig.h*k;o.fontSize=(orig.fontSize||32)*k}if(orig.type==='text'){o.fontSize=Math.max(8,Math.min(200,orig.fontSize*Math.min(sx,sy)));measureText(o)}}}else if(drag.mode==='marquee'){drag.end=p}scheduleRender()}
input=createPointerInput(canvas,{
 point:screenPoint,view:()=>state.view,
 start:e=>{inputCheckpoint={objects:state.objects.slice(),selected:new Set(state.selected)};beginPointer(e)},
 move:movePointer,hover:movePointer,
 end:canceled=>{
  if(canceled&&inputCheckpoint){
   for(const original of drag?.original||[]){const object=inputCheckpoint.objects.find(o=>o.id===original.id);if(object)Object.assign(object,original)}
   state.objects=inputCheckpoint.objects;state.selected=inputCheckpoint.selected;drag=null;syncSelection();scheduleRender();
  }else gestureEnd();inputCheckpoint=null;
 },
 navigate:view=>{state.view=view;scheduleRender()},navigationEnd:()=>{scheduleSave();scheduleRender()}
});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('dblclick',e=>{if(state.tool!=='select')return;const o=hitTop(worldPoint(screenPoint(e)));if(!o?.locked){if(o?.type==='text')textDialog({x:o.x,y:o.y},o);if(o?.type==='formula')formulaDialog(o)}});
