 function generate(){levelDescription.textContent=TASK_LEVELS[topic.value]?.[level.value]||'';taskOptions={topic:topic.value,level:level.value,count:Number(count.value),includeAnswers:answerInput.checked};generated=generateTasks(taskOptions);preview.replaceChildren();for(const [i,t] of generated.entries()){const row=document.createElement('div');row.className='task-row';const question=document.createElement('textarea');question.rows=3;question.maxLength=1000;question.setAttribute('aria-label',`Задание ${i+1}`);question.value=t.question;question.addEventListener('input',()=>t.question=question.value);const answer=document.createElement('details');answer.className='task-answer';const summary=document.createElement('summary');summary.textContent='Показать ответ';const solution=document.createElement('textarea');solution.rows=2;solution.maxLength=500;solution.setAttribute('aria-label',`Ответ ${i+1}`);solution.value=t.answer;solution.addEventListener('input',()=>t.answer=solution.value);answer.append(summary,solution);row.append(question,answer);preview.append(row)}}
