 if(options.includeAnswers){let ay=y;const header=put(x+610,ay,'Ответы',25,'#7265b2',true);ay+=header.h+24;for(const [i,t] of tasks.entries()){const o=put(x+610,ay,`${i+1}. ${t.answer}`,20,'#7265b2');ay+=o.h+18}}
