 const b=union(created),right=workspace.classList.contains('panel-collapsed')||width<900?20:285,aw=Math.max(220,width-right-150),ah=Math.max(200,height-130);const z=Math.max(.08,Math.min(1,aw/(b.w+50),ah/(b.h+50)));state.view={scale:z,x:100+(aw-b.w*z)/2-b.x*z,y:45+(ah-b.h*z)/2-b.y*z};scheduleRender();scheduleSave();toast('Задания добавлены. Каждый пункт можно редактировать двойным щелчком.');
