document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.tool)setTool(b.dataset.tool);else if(b.dataset.action){const fn=actions[b.dataset.action];if(fn)Promise.resolve(fn()).catch(()=>toast('Действие не выполнено. Попробуйте ещё раз.'))}else if(b.dataset.color)updateColor(b.dataset.color);else if(b.dataset.insert)addMath(b.dataset.insert)});
