function isTyping(){const el=document.activeElement;return el&&(el.matches('input,textarea,select')||el.isContentEditable)||$('modal').open||ai?.hasFocus()}
document.addEventListener('keydown',e=>{if(isTyping())return;const mod=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(mod){if(k==='z'){e.preventDefault();undo(e.shiftKey?1:-1)}else if(k==='y'){e.preventDefault();undo(1)}else if(k==='s'){e.preventDefault();saveFile()}else if(k==='a'){e.preventDefault();state.selected=new Set(state.objects.map(o=>o.id));setToolKeepingSelection('select');syncSelection();scheduleRender()}else if(k==='d'){e.preventDefault();duplicate()}else if(k==='c'){e.preventDefault();copySelection()}else if(k==='x'){e.preventDefault();copySelection();removeSelected()}return}if(e.code==='Space'){if(document.activeElement?.matches('button,summary'))return;e.preventDefault();space=true;canvas.style.cursor='grab';return}if(k==='delete'||k==='backspace'){e.preventDefault();removeSelected()}else if(k==='escape'){input?.cancel();setTool('select')}else if(['v','h','p','m','e','l','a','r','o','t'].includes(k))setTool({v:'select',h:'hand',p:'pen',m:'marker',e:'eraser',l:'line',a:'arrow',r:'rectangle',o:'ellipse',t:'text'}[k]);else if(['arrowleft','arrowright','arrowup','arrowdown'].includes(k)){e.preventDefault();const n=e.shiftKey?10:1;for(const o of chosen())if(!o.locked){o.x+=(k==='arrowright'?n:k==='arrowleft'?-n:0);o.y+=(k==='arrowdown'?n:k==='arrowup'?-n:0)}commit()}});
