async function persist(){clearTimeout(saveTimer);const data=clone(scene());boards.set(data.id,data);const serial=++saveSerial,revision=mutationRevision,restoreIds=[...pendingRestores];try{if(db)await new Promise((res,rej)=>{const tx=db.transaction('boards','readwrite');tx.objectStore('boards').put(data);for(const id of restoreIds){const b=boards.get(id);if(b)tx.objectStore('boards').put(b)}tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error)});else localStorage.setItem('axioma-boards-v1',JSON.stringify([...boards.values()]));for(const id of restoreIds)pendingRestores.delete(id);try{localStorage.setItem('axioma-current-v1',state.id)}catch{}if(serial===saveSerial&&revision===mutationRevision){dirty=false;$('save-status').textContent='Сохранено в браузере';$('save-status').classList.remove('save-error')}refreshBoardList()}catch{$('save-status').textContent='Скачайте файл для сохранения';$('save-status').classList.add('save-error');toast('Не удалось сохранить в браузере. Скачайте файл доски кнопкой «Сохранить».')}}
async function initStorage(){try{db=await new Promise((res,rej)=>{const req=indexedDB.open('axioma-board-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('boards',{keyPath:'id'});req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});const list=await new Promise((res,rej)=>{const r=db.transaction('boards').objectStore('boards').getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});boards=new Map(list.map(x=>[x.id,x]))}catch{db=null;try{boards=new Map(JSON.parse(localStorage.getItem('axioma-boards-v1')||'[]').map(x=>[x.id,x]))}catch{boards=new Map()}}let id;try{id=localStorage.getItem('axioma-current-v1')}catch{}const b=boards.get(id)||[...boards.values()][0];if(b){try{Object.assign(state,validateScene(b));state.id=b.id}catch{demo()}}else demo();updateControls();commit();setTool('select');if(!b)requestAnimationFrame(fit)}
